import{_ as t,H as a,f as o,i}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"18 | DreamBooth和LoRA：低成本实现IP专属的AI绘画模型","description":"","frontmatter":{},"headers":[{"level":2,"title":"Textual Inversion","slug":"textual-inversion","link":"#textual-inversion","children":[]},{"level":2,"title":"DreamBooth","slug":"dreambooth","link":"#dreambooth","children":[]},{"level":2,"title":"LoRA","slug":"lora","link":"#lora","children":[]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI绘画核心技术与实战/18｜DreamBooth和LoRA：低成本实现IP专属的AI绘画模型.md","filePath":"AI绘画核心技术与实战/18｜DreamBooth和LoRA：低成本实现IP专属的AI绘画模型.md","lastUpdated":1795562124000}'),r={name:"AI绘画核心技术与实战/18｜DreamBooth和LoRA：低成本实现IP专属的AI绘画模型.md"};function n(s,e,E,p,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_18-dreambooth和lora-低成本实现ip专属的ai绘画模型" tabindex="-1">18 | DreamBooth和LoRA：低成本实现IP专属的AI绘画模型 <a class="header-anchor" href="#_18-dreambooth和lora-低成本实现ip专属的ai绘画模型" aria-label="Permalink to &quot;18 | DreamBooth和LoRA：低成本实现IP专属的AI绘画模型&quot;">​</a></h1><p>你好，我是南柯。</p><p>学完前两章内容，我们已经掌握了 AI 绘画的基本原理，也熟悉了 AI 绘画的经典解决方案。从这一讲开始，我们正式进入课程的综合演练篇，一起探讨图像定制化生成与编辑的经典算法方案。</p><p>使用 Stable Diffusion 模型的时候，基于 prompt 生成图像已经是我们比较熟悉的模式，比如一个人在某个地方做某件事。这种方式生成的图像类似开盲盒，因为我们在看到效果之前，并不确定图中生成的物体和风格是什么样的。</p><p>而接下来我们要学习的定制化图像生成技术就不同了，它的目标是控制指定的一个人在某个地方做某件事，或者控制生成的图片是某只动物，再或者生成的图像是某个确定的风格。</p><p>可不要小看了这个定制化的思想，海外非常流行的 LensaAI 和国内风靡一时的“妙鸭相机”，它们都是定制化图像生成的具体产品方案。今天这一讲，我们要学习三种经典的定制化算法方案，分别是 Textual Inversion、DreamBooth 和 LoRA。</p><h2 id="textual-inversion" tabindex="-1">Textual Inversion <a class="header-anchor" href="#textual-inversion" aria-label="Permalink to &quot;Textual Inversion&quot;">​</a></h2><p>为了帮你更好地理解 Textual Inversion 这个算法，我先带你回顾下 SD 词嵌入向量的使用方式。</p><p>在 SD AI 绘画过程中，我们输入的 prompt 首先会经过 tokenizer 完成分词，得到每个分词的token_id。之后在预训练的词嵌入库中根据 token_id 拿到词嵌入向量，并将这些词嵌入向量拼接在一起，输入到 CLIP 的文本编码器。接着，经过 CLIP 文本编码器提取到的文本表征，便可以通过交叉注意力机制控制图像生成。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/1.png" alt=""></a></p><p>理解了 SD 词嵌入向量的使用，再来学习 Textual Inversion 这个算法就会非常简单。</p><p>Textual Inversion 算法的本质是学习一个全新的词嵌入向量，用于指代定制化的内容。其核心思想便是，对于一个给定的物体或者风格，去学习一个全新的词嵌入向量，并绑定一个符号比如 S*，为其分配一个新的 token_id。这样，每次文生图的时候只需要带上 S*，就能生成我们想要定制化的物体或者风格。</p><p>这个思想很简单，我们来看下这个算法的效果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/2.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/pdf/2208.01618.pdf" target="_blank" rel="noreferrer">https://arxiv.org/pdf/2208.01618.pdf</a></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/3.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/pdf/2208.01618.pdf" target="_blank" rel="noreferrer">https://arxiv.org/pdf/2208.01618.pdf</a></li></ul><p>从前面的图中我们可以看到，对于一个物体或者风格，我们只需要使用 3～5 张图训练，便可以得到新的关键词 S*，从而完成定制化图像生成的任务。</p><p>那么，这个过程具体是如何完成的呢？你可以结合后面这张算法原理图，听我继续分析。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/4.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/pdf/2208.01618.pdf" target="_blank" rel="noreferrer">https://arxiv.org/pdf/2208.01618.pdf</a></li></ul><p>Textual Inversion 的训练过程一共分两步。</p><p>第一，我们需要为你提供的关键词（比如 S*），绑定一个新的 token_id，并初始化这个token_id 对应的词嵌入向量。举例来说，比如原始词嵌入库中包括 20000 个关键词，token_id对应的数值就是 1～20000，那么我们新增关键词 S* 的 token_id 便应该是 20001。</p><p>第二，准备好前人已经训练好的 AI 绘画模型，比如 Stable Diffusion 模型或者 DALL-E 2 模型。训练过程中 CLIP 文本编码器、UNet 等模型的权重需要全部固定住。按照对应 AI 绘画模型的标准训练方法，在你提供的 3-5 张图片上进行训练。</p><p>整个过程中，只有你新初始化的词嵌入向量是可以学习的。当训练完成后，你便得到了你的定制化词嵌入向量，它的作用是表达训练图片中的物体或者风格。</p><p>我想提示你注意两点。第一，得到的词嵌入向量是和训练使用的 AI 绘画模型绑定在一起的。第二，Textual Inversion 的训练也可以同时优化多个新增的词嵌入向量。你可以点击链接查看 Textual Inversion 的训练代码，加深了解。</p><h2 id="dreambooth" tabindex="-1">DreamBooth <a class="header-anchor" href="#dreambooth" aria-label="Permalink to &quot;DreamBooth&quot;">​</a></h2><p>由于 Textual Inversion 训练过程中的可学习参数非常少，通常只有 512 或者 768 个浮点数，所以它的定制化生成能力并不是很强。在市场上各种常见的定制化生成产品中，更常用的方法是 DreamBooth。</p><p>关于 DreamBooth 这个命名有个很有意思的小插曲。Google 团队是这样解释的：DreamBooth 就像是一个摄影棚（PhotoBooth），但是一旦拍摄主体被记录下来，它可以被合成到你梦想的任何地方。</p><p>DreamBooth 同样是需要上传 3～5 张图，使用一个新的描述词[V]，它同样可以定制化一个物体或者一种风格。DreamBooth 的生成效果你可以参考后面的图片。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/5.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/abs/2208.12242" target="_blank" rel="noreferrer">https://arxiv.org/abs/2208.12242</a></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/6.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/abs/2208.12242" target="_blank" rel="noreferrer">https://arxiv.org/abs/2208.12242</a></li></ul><p>那么 DreamBooth 是怎么实现的呢？我们先来看看论文给出的方案图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/7.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/abs/2208.12242" target="_blank" rel="noreferrer">https://arxiv.org/abs/2208.12242</a></li></ul><p>我来解释下这个方案。算法过程还是两步。</p><p>第一，选择一个罕见的词作为你的关键词，比如 CSS。不同于 Textual Inversion，这里的词不需要绑定全新的词嵌入向量。</p><p>第二，准备好前人已经训练好的 AI 绘画模型，比如 Stable Diffusion 模型或者 DALL-E 2 模型。训练过程中 UNet 模型的权重需要打开。然后，我们要按照对应 AI 绘画模型的标准训练方法，在你提供的 3-5 张图片上进行训练。</p><p>你可能会问，只用 3-5 张图去优化 UNet 这么多参数，不会造成模型的过拟合么？比如使用 3-5 张你自己的小狗得到的模型，就再也无法生成其他样式的小狗。</p><p>答案是会的。这样得到的模型，无论你的 prompt 是 “a CSS dog” 或者是 “a dog”，都会得到训练用的小狗。</p><p>为了解决这个问题，论文作者提出了保留损失（preservation loss）这个应对方法。具体操作就是先使用 AI 绘画模型生成一批小狗的图片，在训练 DreamBooth 的时候，这批图像也加入AI 绘画模型的训练。通过这种方式得到的模型便可以有效地避免过拟合。</p><p>这里我想提醒你留意，训练 DreamBooth 的时候，CLIP 文本编码器也可以打开训练，实践证明这样做可以提升定制化图像生成的算法效果。</p><p>我用一句话概括一下 Textual Inversion 和 DreamBooth 的区别：前者只会优化一个或几个词嵌入向量，后者会对整个 AI 绘画模型做微调。</p><p>接下来，我们不妨对比下 Textual Inversion 和 DreamBooth 的算法表现。在实际使用中，推荐你用 DreamBooth 这个方案。你可以点击链接查看训练代码。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/8.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/abs/2208.12242" target="_blank" rel="noreferrer">https://arxiv.org/abs/2208.12242</a></li></ul><h2 id="lora" tabindex="-1">LoRA <a class="header-anchor" href="#lora" aria-label="Permalink to &quot;LoRA&quot;">​</a></h2><p>如果我们想实现 DreamBooth 定制化图像生成的效果，又不希望更改原有 AI 绘画模型的模型权重，还有什么思路呢？</p><p>答案是使用 LoRA。</p><p>LoRA 的全称是 Low-Rank Adaption of large language model。从名字我们能一眼看出，这个技术最开始是为大语言模型设计的。</p><p>在了解它的技术原理之前，我们要先复习一个线性代数的基本概念：矩阵的秩。</p><p>举个例子，如果你有一个 2x2 的矩阵（也就是有 2 行 2 列的矩阵），第 2 行是第 1 行的两倍，那么这个矩阵的秩就是 1，而不是 2，即使这个矩阵有两行。因为第 2 行实际上并没有提供新的信息，它只是第 1 行的两倍而已。所以，我们可以把秩理解为矩阵所能提供的信息量或者矩阵所描述的空间维度。</p><p>对于深度学习模型而言，我们学习得到的权重便是一个巨大的矩阵 W。</p><p>我们假设这个矩阵的维度是 dxd，而它的秩是 r。我们可以找到两个矩阵 A 和 B，其中 A 的大小是 dxr，B 的大小是 rxd，使得 W=AB。这在数学上叫做矩阵的秩因子分解。一般来说，r 远小于 d。</p><p>LoRA 便是利用了矩阵的这个性质。在训练过程中，W 保持固定，优化矩阵 A 和矩阵 B 的权重。这样，W + AB 便是我们最终要用的模型权重。理解了这些，我们再去看 LoRA 论文中给出的方案图就简单多了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/9.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/abs/2106.09685" target="_blank" rel="noreferrer">https://arxiv.org/abs/2106.09685</a></li></ul><p>你可能在 Civitai 上下载过不少基础模型权重和 LoRA 模型权重。你有没有发现，基础模型动辄 3-4GB，而 LoRA 模型最大不过 200M，这是为什么呢？</p><p>还是以上面的矩阵运算为例，我们假定 W 的维度 d=10000，W 的秩 r=100。那么原始权重的参数量便是 100M，而 A 和 B 的参数量只有 1M。这便是 LoRA 模型远远小于基础模型的原因。</p><p>那么 LoRA 的效果如何呢？在原始论文中作者设计了一个实验，在某个特定数据集上微调GPT-3 的全部参数，对比只微调 LoRA 模型的参数。</p><p>从下面的图中你可以看到，GPT-3 的全部参数有 1750 亿，而训练的 LoRA 只有 37.7M。后者大概只占全部参数的万分之二，在所有测试指标上都超过了全量参数微调。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/10.png" alt=""></a></p><ul><li>图像来源：<a href="https://arxiv.org/abs/2106.09685" target="_blank" rel="noreferrer">https://arxiv.org/abs/2106.09685</a></li></ul><p>LoRA 算法一经提出，便开始席卷 AI 绘画圈。相比 GPT-3 1750 亿的参数，负责去噪的 UNet通常只有几百 M 的参数，顶多算是小模型。但是 LoRA 仍然能有效减少可学习参数，为我们的模型训练和存储提供便利。</p><p>我们使用 LoRA 模型的时候，加入 LoRA 的参数相当于给原始模型添加了新功能，不用的时候还可以将 LoRA 功能关闭，一举两得。这也就解释了我们实战 1 中为何要下载基础模型（比如SD1.5）和 LoRA 模型（比如我们实战 1 用的 IN LoRA 模型）。</p><p>回到我们今天的话题定制化图像生成。我们已经知道，DreamBooth 的训练是对整个 AI 绘画模型做微调。这个过程当然也可以引入 LoRA 模型，来做 CLIP 文本编码器和 UNet 模型的权重微调。</p><p>使用 LoRA 相比于微调原始模型有哪些好处呢？我认为有以下四点。</p><p>第一，可以保持基础模型不变，将 LoRA 当成“插件”，可以添加、删除、替换和组合使用。</p><p>第二，LoRA 的参数量少，训练效率高，对于硬件环境的要求更低。普通人也都训练得动。</p><p>第三，训练后可以直接将 LoRA 添加到原模型中，而且模型的推理速度不受任何影响。比如在AI 绘画任务中，我们将 LoRA 模型与基础模型组合使用后，生成图片的速度不会受到影响。</p><p>第四，对于妙鸭相机这类头像产品，往往需要在一段时间内保存用户的模型权重，保存 LoRA权重相比保存完整 SD 模型能节省很大的空间。</p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>今天我们学习了定制化图像生成技术，包括 Textual Inversion 和 DreamBooth 这两种算法方案，以及如何使用 LoRA 来减少 DreamBooth 训练过程中的模型参数。</p><p>Textual Inversion 技术通过新增一个或者多个可学习的词嵌入向量，只需 3-5 张图便可实现定制化图像生成。它的优点是不影响基础模型性能、得到的权重只是几百个浮点数，缺点是很多时候定制化生成的效果并不理想。</p><p>DreamBooth 并不新增词嵌入向量，而是使用用户提供的 3-5 张图优化整个 AI 绘画模型。其优点是定制化生成的效果好。缺点是影响基础模型性能、得到的模型权重与原始模型相当，并且 DreamBooth 容易造成模型的过拟合，需要引入保留损失来抑制过拟合。</p><p>最后我们学习了 LoRA 这个技术。简单来说，它的工作原理是将处理一个大的权重矩阵的任务转变为处理两个较小的权重矩阵。这两个小的权重矩阵可以看作是原始大矩阵的一种分解表示。LoRA 技术不仅可以用于大语言模型的训练，还能够用于 AI 绘画模型的微调。</p><p>这一讲的重点内容，我用导图方式做了整理，供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/18/11.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>除了我们今天提到的 LensaAI 和妙鸭相机，你还知道哪些 AI 产品，用到了我们今天学习的定制化图像生成技术？</p><p>欢迎你在留言区和我交流讨论。如果这一讲对你有启发，也推荐你分享给身边更多同事、朋友。</p>',83)])])}const g=t(r,[["render",n]]);export{A as __pageData,g as default};
